	decode := func(raw []byte) any {
		t.Helper()
		var out any
		d := json.NewDecoder(bytes.NewReader(raw))
		d.UseNumber()
		if err := d.Decode(&out); err != nil {
			t.Fatal(err)
		}
		return out
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			model := c.makeModel()
			if err := json.Unmarshal([]byte(c.input), model); err != nil {
				t.Fatal(err)
			}
			raw, err := json.Marshal(model)
			if err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(decode([]byte(c.input)), decode(raw)) {
				t.Fatalf("model changed JSON shape: input %s, output %s", c.input, raw)
			}
		})
	}
